using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TravelControlTests
{
 static byte[] View(WorldSession s){var v=s.GetBranchView(ContractFixture.Officer);return System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(new{v.Position,v.Heading,v.DistanceMm,v.Walking,v.ArrivalAt,v.PlannedEdges,v.KnownBlockedEdges,v.NextPosition,v.StepDistanceMm});}
 static WorldSession New()=>new(TravelControl.Create());
 static void Go(WorldSession s,string destination){Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:trip/"+s.DiagnosticSnapshot().Requests.Length,destination),s.Revision).Code);s.AdvanceTo(s.Seconds+1);}
 static void Arrive(WorldSession s)=>s.AdvanceTo(s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[^1].EndAt);
 static PersonalTravelRequest Decide(WorldSession s,string? dest,string id="request:decision"){var i=TravelControl.Request(s.DiagnosticSnapshot(),id,dest);Assert.Equal(ResultCode.Accepted,s.ChangeTravel(i,s.Revision).Code);return i;}
 static JourneyLeg Sea(WorldSession s)=>s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs.First(l=>NationalRoutes.Sea(l.Edge));
 [Fact] public void LandRedirectKeepsPositionAndOldEdgeUntilNextNode(){var s=New();Go(s,"sakai");var old=s.DiagnosticSnapshot().Branches!.Journeys.Last();s.AdvanceTo(old.Legs[0].StartAt+100);var before=s.GetBranchView(ContractFixture.Officer);Decide(s,"edo");Assert.Equal(before.Position,s.GetBranchView(ContractFixture.Officer).Position);Assert.Equal(before.PlannedEdges,s.GetBranchView(ContractFixture.Officer).PlannedEdges);Assert.Equal(before.ArrivalAt,s.GetBranchView(ContractFixture.Officer).ArrivalAt);Assert.Null(s.DiagnosticSnapshot().TravelDecisions!.Single().AppliedAt);s.AdvanceTo(old.Legs[0].EndAt-1);Assert.Equal(old.Legs,s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs);s.AdvanceTo(old.Legs[0].EndAt);var w=s.DiagnosticSnapshot();Assert.Equal("redirected",w.TravelDecisions!.Single().Result);Assert.Equal(old.Legs[0],w.Branches!.Journeys.Single().Legs[0]);Assert.Equal(old.Legs[0].EndAt,w.TravelDecisions!.Single().AppliedAt);Arrive(s);Assert.Equal(new EntityId("site:edo"),s.GetActorView(ContractFixture.Officer).Location.Site);}
 [Fact] public void CancellationKeepsActorAtPortAndAllowsNewDeparture(){var s=New();Go(s,"sumoto");var l=Sea(s);s.AdvanceTo(l.StartAt);var p=s.GetBranchView(ContractFixture.Officer).Position;Decide(s,null);Assert.Equal(p,s.GetBranchView(ContractFixture.Officer).Position);Assert.Equal(RegionalCampaign.Site(l.From),s.GetActorView(ContractFixture.Officer).Location.Site);Assert.Equal(ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks.Single().Execution);s.AdvanceTo(l.EndAt+1);Assert.Equal(p,s.GetBranchView(ContractFixture.Officer).Position);Go(s,"castle");Assert.Equal(l.From,s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[0].From);Arrive(s);Assert.Equal(ContractFixture.Castle,s.GetActorView(ContractFixture.Officer).Location.Site);}
 [Theory][InlineData(-1,true)][InlineData(0,false)][InlineData(1,false)] public void DepartureBoundaryIsStrict(long offset,bool accepted){var s=New();Go(s,"sumoto");var l=Sea(s);var at=TravelWorld.Departure(s.DiagnosticSnapshot(),l.Edge,l.StartAt)+offset;s.AdvanceTo(at);var i=TravelControl.Request(s.DiagnosticSnapshot(),"request:cancel",null);var before=ContractJson.Write(s.DiagnosticSnapshot());var result=s.ChangeTravel(i,s.Revision);Assert.Equal(accepted?ResultCode.Accepted:ResultCode.NotAvailable,result.Code);if(!accepted)Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
 [Fact] public void SeaRedirectFinishesCurrentCrossingBeforeChangingCourse(){var s=New();Go(s,"sumoto");var l=Sea(s);s.AdvanceTo(TravelWorld.Departure(s.DiagnosticSnapshot(),l.Edge,l.StartAt)+100);var p=s.GetBranchView(ContractFixture.Officer).Position;Decide(s,"castle");Assert.Equal(p,s.GetBranchView(ContractFixture.Officer).Position);Assert.Equal(l.EndAt,s.DiagnosticSnapshot().TravelDecisions!.Single().EffectiveAt);s.AdvanceTo(l.EndAt);Assert.Equal(l.To,s.DiagnosticSnapshot().TravelDecisions!.Single().Node);Arrive(s);Assert.Equal(ContractFixture.Castle,s.GetActorView(ContractFixture.Officer).Location.Site);}
 [Fact] public void SameIdIsIdempotentAndConflictingBodyIsRejected(){var s=New();Go(s,"sakai");s.AdvanceTo(100);var i=Decide(s,"edo");Assert.Equal(ResultCode.AlreadyAccepted,s.ChangeTravel(i,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ChangeTravel(i with{Destination=new EntityId("site:kofu")},s.Revision).Code);s.AdvanceTo(s.DiagnosticSnapshot().TravelDecisions!.Single().EffectiveAt);Assert.Equal(ResultCode.AlreadyAccepted,s.ChangeTravel(i,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().EffectLedger,e=>e.BusinessKey=="personal-travel/"+i.Id.Value);}
 [Fact] public void WrongActorStaleRevisionAndOverlappingDecisionsDoNotMutate(){var s=New();Go(s,"sakai");s.AdvanceTo(100);var i=TravelControl.Request(s.DiagnosticSnapshot(),"request:one","edo");var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.StateChanged,s.ChangeTravel(i,s.Revision-1).Code);Assert.Equal(ResultCode.NotAvailable,s.ChangeTravel(i with{Actor=ContractFixture.Lord},s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Decide(s,"edo");Assert.Equal(ResultCode.NotAvailable,s.ChangeTravel(i,s.Revision).Code);}
 [Fact] public void RedirectCanStopAtNextNodeAndThenStartAnotherTrip(){var s=New();Go(s,"sakai");var l=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs[0];s.AdvanceTo(100);Decide(s,l.To);s.AdvanceTo(l.EndAt);Assert.Equal(ExecutionPhase.Completed,s.DiagnosticSnapshot().Tasks.Single().Execution);Assert.Equal(RegionalCampaign.Site(l.To),s.GetActorView(ContractFixture.Officer).Location.Site);Go(s,"castle");Arrive(s);}
 [Fact] public void ASecondRedirectPreservesBothTraveledPrefixes(){var s=New();Go(s,"sakai");s.AdvanceTo(100);Decide(s,"edo","request:first");s.AdvanceTo(s.DiagnosticSnapshot().TravelDecisions!.Last().EffectiveAt+1);Decide(s,"kofu","request:second");s.AdvanceTo(s.DiagnosticSnapshot().TravelDecisions!.Last().EffectiveAt);Arrive(s);Assert.Equal(new EntityId("site:kofu"),s.GetActorView(ContractFixture.Officer).Location.Site);Assert.Equal(2,s.DiagnosticSnapshot().TravelDecisions!.Count(d=>d.Result=="redirected"));}
 [Fact] public void PortWaitingRequiresCancelBeforeChoosingAnotherDestination(){var s=New();Go(s,"sumoto");s.AdvanceTo(Sea(s).StartAt);var i=TravelControl.Request(s.DiagnosticSnapshot(),"request:wrong","edo");Assert.Equal(ResultCode.NotAvailable,s.ChangeTravel(i,s.Revision).Code);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)] public void DecisionRestoreAndContinuationPreserveExactPositionAndEffects(int phase){var s=New();Go(s,"sumoto");if(phase<2){s.AdvanceTo(100);Decide(s,"edo");if(phase==1)s.AdvanceTo(s.DiagnosticSnapshot().TravelDecisions!.Single().EffectiveAt+1);}else{s.AdvanceTo(Sea(s).StartAt);if(phase==3)Decide(s,null);}var root=Path.Combine(Path.GetTempPath(),"travel-control-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,TravelControl.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.375,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(View(s),View(host.Current));host.Current.SetPaused(false);if(phase==2){Decide(s,null);Decide(host.Current,null);}s.AdvanceTo(20000000);host.Current.AdvanceTo(20000000);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().TravelDecisions),ContractJson.Write(host.Current.DiagnosticSnapshot().TravelDecisions));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Branches),ContractJson.Write(host.Current.DiagnosticSnapshot().Branches));Assert.Equal(View(s),View(host.Current));}
 [Fact] public void OldTravelSaveCannotBeSilentlyUpgraded(){var root=Path.Combine(Path.GetTempPath(),"travel-control-old-"+Guid.NewGuid().ToString("N"));var s=new WorldSession(TravelWorld.Create());new GenerationSaveStore(root,TravelWorld.Create().Definitions).Save(s,"test",s.DiagnosticSnapshot().WorldId,new(0,1));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,TravelControl.Create().Definitions).Prepare("test"));}
 [Fact] public void MissingModuleForgedEffectAndRewrittenPrefixAreRejected(){var s=New();Go(s,"sakai");s.AdvanceTo(100);Decide(s,"edo");var w=s.DiagnosticSnapshot();w.TravelDecisions=null;Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));s.AdvanceTo(s.DiagnosticSnapshot().TravelDecisions!.Single().EffectiveAt);w=s.DiagnosticSnapshot();w.EffectLedger=w.EffectLedger.Where(e=>!e.BusinessKey.StartsWith("personal-travel/")).ToArray();Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));w=s.DiagnosticSnapshot();var d=w.TravelDecisions![0];w.TravelDecisions=[d with{EffectiveAt=d.EffectiveAt-1}];Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
 [Fact] public void UnknownClosureIsNotUsedWhenChoosingNewDestination(){var a=TravelControl.Create();var b=TravelControl.Create();b.Branches=b.Branches! with{BlockedEdges=["nation-sakai-sumoto"]};b.Couriers=b.Couriers! with{InitialBlocked=b.Branches.BlockedEdges};var x=new WorldSession(a);var y=new WorldSession(b);Go(x,"sakai");Go(y,"sakai");x.AdvanceTo(100);y.AdvanceTo(100);Decide(x,"sumoto");Decide(y,"sumoto");Assert.Equal(ContractJson.Write(x.DiagnosticSnapshot().TravelDecisions),ContractJson.Write(y.DiagnosticSnapshot().TravelDecisions));}
 [Fact] public void FailedCommitCannotLeaveHalfAppliedPortCancellation(){var s=New();Go(s,"sumoto");s.AdvanceTo(Sea(s).StartAt);var before=ContractJson.Write(s.DiagnosticSnapshot());var i=TravelControl.Request(s.DiagnosticSnapshot(),"request:atomic",null);Assert.Throws<InvalidOperationException>(()=>s.ChangeTravel(i,s.Revision,()=>throw new InvalidOperationException("injected commit failure")));Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,s.ChangeTravel(i,s.Revision).Code);}
 [Fact] public void MalformedAndUnknownDestinationRequestsAreRejectedWithoutMutation(){var s=New();Go(s,"sakai");s.AdvanceTo(100);var i=TravelControl.Request(s.DiagnosticSnapshot(),"request:invalid","edo");var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ChangeTravel(i with{Id=default},s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ChangeTravel(i with{Destination=new EntityId("site:missing")},s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
 [Fact] public void MaximumLengthRequestIdCanCommitItsDeferredEffect(){var s=New();Go(s,"sakai");s.AdvanceTo(100);var i=Decide(s,"edo","request:"+new string('x',120));s.AdvanceTo(s.DiagnosticSnapshot().TravelDecisions!.Single().EffectiveAt);Assert.Single(s.DiagnosticSnapshot().EffectLedger,e=>e.BusinessKey=="personal-travel/"+i.Id.Value);}
}
